if(route==='/forgot-password'&&req.method==='POST'){const email=clean(req.body.email,254).toLowerCase(),ip=req.headers['x-forwarded-for']||'unknown';await limited(`reset-ip:${ip}`,8);await limited(`reset-email:${email}`,3);const target=(await sql('SELECT id,email FROM users WHERE email=$1 AND active=true',[email]))[0];if(target){const token=randomBytes(32).toString('hex');await sql('DELETE FROM password_resets WHERE user_id=$1 OR expires_at<now()',[target.id]);await sql('INSERT INTO password_resets(token,user_id,expires_at) VALUES($1,$2,now()+interval \'30 minutes\')',[hash(token),target.id]);await sendResetEmail(target.email,token);await audit(target.id,'password.reset.request',target.id);}return api(res,200,{ok:true});}
if(route==='/reset-password'&&req.method==='POST'){const token=typeof req.body.token==='string'?req.body.token:'',next=typeof req.body.password==='string'?req.body.password:'';if(!/^[a-f0-9]{64}$/.test(token)||next.length<12||next.length>128)throw new AppError('O link ou a nova senha não é válido.');const used=await sql('UPDATE password_resets SET used_at=now() WHERE token=$1 AND used_at IS NULL AND expires_at>now() RETURNING user_id',[hash(token)]);if(!used.length)throw new AppError('Este link expirou ou já foi usado. Solicite outro.');const userId=used[0].user_id;await sql('UPDATE users SET password=$1,must_change=false WHERE id=$2',[await passHash(next),userId]);await sql('DELETE FROM sessions WHERE user_id=$1',[userId]);await audit(userId,'password.reset.complete',userId);return api(res,200,{ok:true});}
const u=await session(req);if(!u)throw new AppError('Sua sessão expirou. Entre novamente.',401);if(route==='/logout'&&req.method==='POST'){const t=cookies(req)[cookieName];if(t)await sql('DELETE FROM sessions WHERE token=$1',[hash(t)]);return api(res,200,{ok:true},{'Set-Cookie':`${cookieName}=; Path=/; HttpOnly; Secure; SameSite=Strict; Max-Age=0`});}
if(route==='/password'&&req.method==='POST'){const next=typeof req.body.password==='string'?req.body.password:'';if(next.length<12||next.length>128)throw new AppError('Use uma senha com 12 a 128 caracteres.');if(!await checkPass(typeof req.body.currentPassword==='string'?req.body.currentPassword.slice(0,128):'',u.password))throw new AppError('A senha atual está incorreta.',403);await sql('UPDATE users SET password=$1,must_change=false WHERE id=$2',[await passHash(next),u.id]);await sql('DELETE FROM sessions WHERE user_id=$1',[u.id]);await setSession(res,u.id);return api(res,200,{ok:true});}
if(u.must_change)throw new AppError('Defina uma nova senha antes de continuar.',428);await ensureLeadSchema();
if(route==='/whatsapp/status'&&req.method==='GET'){if(!bridge)throw new AppError('Configure WHATSAPP_AUTH_DIR em um volume persistente da VPS para usar o WhatsApp interno.',503);const state=await bridge.state();return api(res,200,{status:state.status,qr:u.role==='admin'?state.qr:'',phone:u.role==='admin'?state.phone:''});}
if(route==='/whatsapp/conversations'&&req.method==='GET'){
  const rows=await sql(`SELECT c.id,c.name,c.city,c.state,c.whatsapp,l.saved_by,u.name saved_by_name,m.body last_body,m.direction last_direction,m.created_at last_at
    FROM leads l JOIN companies c ON c.id=l.company_id JOIN users u ON u.id=l.saved_by
    LEFT JOIN LATERAL (SELECT body,direction,created_at FROM whatsapp_messages WHERE company_id=c.id ORDER BY created_at DESC,id DESC LIMIT 1) m ON true
    WHERE c.whatsapp<>'' AND ($1::boolean OR l.saved_by=$2)
    ORDER BY m.created_at DESC NULLS LAST,c.name LIMIT 1000`,[u.role==='admin',u.id]);
  return api(res,200,{conversations:rows.map(r=>({id:r.id,name:r.name,city:r.city,state:r.state,whatsapp:r.whatsapp,savedBy:r.saved_by,savedByName:r.saved_by_name,lastBody:r.last_body,lastDirection:r.last_direction,lastAt:r.last_at}))});
}
const chat=route.match(/^\/whatsapp\/leads\/([a-f0-9-]+)$/);if(chat&&(req.method==='GET'||req.method==='POST')){if(!bridge)throw new AppError('WhatsApp interno não configurado nesta instalação.',503);const lead=(await sql('SELECT l.saved_by,c.whatsapp FROM leads l JOIN companies c ON c.id=l.company_id WHERE l.company_id=$1',[chat[1]]))[0];if(!lead||(u.role!=='admin'&&lead.saved_by!==u.id))throw new AppError('Lead não encontrado.',404);if(req.method==='GET'){const rows=await sql('SELECT m.id,m.direction,m.body,m.created_at,m.user_id,u.name user_name FROM (SELECT * FROM whatsapp_messages WHERE company_id=$1 ORDER BY created_at DESC LIMIT 100) m LEFT JOIN users u ON u.id=m.user_id ORDER BY m.created_at ASC',[chat[1]]);const state=await bridge.state();return api(res,200,{status:state.status,messages:rows.map(m=>({id:m.id,direction:m.direction,body:m.body,createdAt:m.created_at,userId:m.user_id,userName:m.user_name}))});}const body=clean(req.body.text,3000);if(!body)throw new AppError('Digite uma mensagem antes de enviar.');let sent;try{sent=await bridge.send(lead.whatsapp,body)}catch(error){throw new AppError(error.message,503)}await sql("INSERT INTO whatsapp_messages(company_id,message_id,direction,body,user_id,created_at) VALUES($1,$2,'out',$3,$4,$5) ON CONFLICT(message_id) DO NOTHING",[chat[1],sent.messageId,body,u.id,sent.sentAt]);await audit(u.id,'whatsapp.send',chat[1]);return api(res,200,{ok:true});}
if(route==='/google-places'&&req.method==='POST'){const result=await searchGooglePlaces(req.body);await audit(u.id,'google.places.search',result.query);return api(res,200,result);}
if(route==='/meta'&&req.method==='GET')return api(res,200,{states:STATES,segments:SEGMENTS,sizes:SIZES,statuses:STATUSES,providerConfigured:!!process.env.PROSPECT_API_URL});
if(route==='/companies'&&req.method==='GET')return api(res,200,{companies:await companies(req.query,false,u),providerConfigured:!!process.env.PROSPECT_API_URL});
if(route==='/companies'&&req.method==='POST'){const result=await insertCompany(req.body,u.id);return api(res,result.duplicate?200:201,result);}
if(route==='/search'&&req.method==='POST'){const provider=process.env.PROSPECT_API_URL;if(!provider)throw new AppError('A fonte de empresas ainda não foi conectada. Cadastre empresas verificadas para pesquisar na base da equipe.',503);const filters={state:clean(req.body.state,2),city:clean(req.body.city,100),segment:clean(req.body.segment,50),size:clean(req.body.size,20)};if((filters.state&&!STATES.includes(filters.state))||(filters.segment&&!SEGMENTS.includes(filters.segment))||(filters.size&&!SIZES.includes(filters.size)))throw new AppError('Filtros inválidos.');let response;try{response=await fetch(provider,{method:'POST',redirect:'error',headers:{'Content-Type':'application/json',...(process.env.PROSPECT_API_KEY?{Authorization:'Bearer '+process.env.PROSPECT_API_KEY}:{})},body:JSON.stringify(filters),signal:AbortSignal.timeout(20_000)});}catch{throw new AppError('Não foi possível consultar a fonte. Tente novamente.',502);}if(!response.ok)throw new AppError('A fonte de empresas está indisponível. Tente novamente mais tarde.',502);let payload;try{payload=await response.json();}catch{throw new AppError('A fonte retornou dados inválidos.',502);}if(!Array.isArray(payload.companies)||payload.companies.length>100)throw new AppError('Resposta incompatível da fonte de empresas.',502);let imported=0,skipped=0;for(const company of payload.companies){try{const result=await insertCompany(company,u.id);if(!result.duplicate)imported++;}catch(error){if(error instanceof AppError)skipped++;else throw error;}}await audit(u.id,'provider.search',String(imported)+'/'+String(skipped));return api(res,200,{companies:await companies(filters),imported,skipped});}
if(route==='/leads'&&req.method==='GET')return api(res,200,{companies:await companies(req.query,true,u)});
if(route==='/leads'&&req.method==='POST'){const id=clean(req.body.companyId,40);if(!(await sql('SELECT 1 FROM companies WHERE id=$1',[id])).length)throw new AppError('Empresa não encontrada.',404);const r=await sql('INSERT INTO leads(company_id,saved_by) VALUES($1,$2) ON CONFLICT(company_id) DO NOTHING RETURNING company_id',[id,u.id]);if(r.length)await audit(u.id,'lead.save',id);return api(res,200,{duplicate:!r.length});}
const activities=route.match(/^\/leads\/([a-f0-9-]+)\/activities$/);if(activities&&req.method==='GET'){const owner=(await sql('SELECT saved_by FROM leads WHERE company_id=$1',[activities[1]]))[0];if(!owner||(u.role!=='admin'&&owner.saved_by!==u.id))throw new AppError('Lead não encontrado.',404);const rows=await sql('SELECT a.*,u.name user_name FROM lead_activities a JOIN users u ON u.id=a.user_id WHERE a.company_id=$1 ORDER BY a.created_at DESC LIMIT 30',[activities[1]]);return api(res,200,{activities:rows.map(a=>({id:a.id,userName:a.user_name,equipmentInterest:a.equipment_interest,contactResult:a.contact_result,notes:a.notes,createdAt:a.created_at}))});}
const lead=route.match(/^\/leads\/([a-f0-9-]+)$/);if(lead&&req.method==='PATCH'){if(!STATUSES.includes(req.body.status)||!Number.isInteger(req.body.version))throw new AppError('Status ou versão inválidos.');const equipment=clean(req.body.equipmentInterest,120),result=clean(req.body.contactResult,80),notes=clean(req.body.notes,5000),next=req.body.nextContactAt?new Date(req.body.nextContactAt):null;if(result&&!['Contato iniciado','Sem resposta','Conversa em andamento','Proposta solicitada','Sem interesse'].includes(result))throw new AppError('Selecione um resultado de contato válido.');if(next&&Number.isNaN(next.getTime()))throw new AppError('Informe uma data válida para o próximo contato.');const r=await sql(`UPDATE leads SET status=$1,notes=$2,equipment_interest=$3,contact_result=CASE WHEN $4<>'' THEN $4 ELSE contact_result END,last_contact_at=CASE WHEN $4<>'' THEN now() ELSE last_contact_at END,next_contact_at=$5,version=version+1 WHERE company_id=$6 AND version=$7 AND (saved_by=$8 OR $9='admin') RETURNING company_id`,[req.body.status,notes,equipment,result,next?.toISOString()||null,lead[1],req.body.version,u.id,u.role]);if(!r.length)throw new AppError('Este lead foi alterado ou não pertence à sua carteira. Reabra os detalhes.',409);if(result)await sql('INSERT INTO lead_activities(company_id,user_id,equipment_interest,contact_result,notes) VALUES($1,$2,$3,$4,$5)',[lead[1],u.id,equipment,result,notes]);await audit(u.id,'lead.update',lead[1]);return api(res,200,{ok:true});}
if(route.startsWith('/users')){if(u.role!=='admin')throw new AppError('Apenas administradores podem gerenciar usuários.',403);if(route==='/users'&&req.method==='GET')return api(res,200,{users:(await sql('SELECT * FROM users ORDER BY name')).map(publicUser)});if(route==='/users'&&req.method==='POST')throw new AppError('Esta operação possui somente três contas de acesso.',403);const match=route.match(/^\/users\/([a-f0-9-]+)$/);if(match&&req.method==='PATCH'){const target=(await sql('SELECT * FROM users WHERE id=$1',[match[1]]))[0];if(!target)throw new AppError('Usuário não encontrado.',404);const active=typeof req.body.active==='boolean'?req.body.active:target.active,role=['admin','seller'].includes(req.body.role)?req.body.role:target.role;if(target.id===u.id&&!active)throw new AppError('Você não pode desativar seu próprio acesso.');const admins=(await sql('SELECT count(*)::int AS count FROM users WHERE role=\'admin\' AND active=true'))[0].count;if(target.role==='admin'&&target.active&&(!active||role!=='admin')&&admins<=1)throw new AppError('Mantenha pelo menos um administrador ativo.');let password=target.password,mustChange=target.must_change;if(req.body.password){if(typeof req.body.password!=='string'||req.body.password.length<12||req.body.password.length>128)throw new AppError('Use uma senha com 12 a 128 caracteres.');password=await passHash(req.body.password);mustChange=true;}await sql('UPDATE users SET active=$1,role=$2,password=$3,must_change=$4 WHERE id=$5',[active,role,password,mustChange,target.id]);await sql('DELETE FROM sessions WHERE user_id=$1',[target.id]);await audit(u.id,'user.update',target.id);return api(res,200,{ok:true});}}
throw new AppError('Recurso não encontrado.',404);
